cd /app && cat > src/setting/dto/scraperRoleAuthorizer.ts <<'EOF'
import { Injectable, Logger } from '@nestjs/common';
import {
    ValidationOptions,
    registerDecorator,
    ValidationArguments,
    ValidatorConstraintInterface,
    ValidatorConstraint,
} from 'class-validator';
import { STSClient, AssumeRoleCommand } from '@aws-sdk/client-sts';
import { getInstanceWithFilters } from '../../utils/aws/awsEc2.js';
import { CloudIAM } from './update-settings.dto.js';

/**
 * Returns true when the supplied cloudIAM block describes a "disconnect" request,
 * i.e. the customer intends to detach their scraper role. A disconnect is signalled
 * by a blank (empty / whitespace only) iamRoleArn.
 */
export function isScraperRoleDisconnect(cloudIAM?: CloudIAM | null): boolean {
    if (!cloudIAM || typeof cloudIAM !== 'object') {
        return false;
    }
    const { iamRoleArn } = cloudIAM;
    return typeof iamRoleArn === 'string' && iamRoleArn.trim().length === 0;
}

/**
 * Returns true when a cloudIAM block is present but does not name a role at all.
 * This is an invalid settings block (as opposed to a blank role, which is a disconnect).
 */
export function scraperRoleBlockNamesNoRole(cloudIAM?: CloudIAM | null): boolean {
    if (!cloudIAM || typeof cloudIAM !== 'object') {
        return false;
    }
    return typeof cloudIAM.iamRoleArn !== 'string';
}

/**
 * Proves that a customer supplied scraper role can actually be used for collection before
 * it is saved. Two things have to hold, and either failure is a bad request:
 *   1. The role can be assumed by the platform identity using the supplied external id.
 *   2. The credentials that come back can read the EC2 instance inventory that collection uses.
 *
 * A blank role is a disconnect and is accepted here (the external id is cleared when the
 * settings are persisted). A block that names no role at all is rejected as invalid.
 */
@ValidatorConstraint({ name: 'AssumableScraperRoleRule', async: true })
@Injectable()
export class AssumableScraperRoleRule implements ValidatorConstraintInterface {
    private static readonly logger = new Logger(AssumableScraperRoleRule.name);

    async validate(cloudIAM: CloudIAM, _args: ValidationArguments): Promise<boolean> {
        // Nothing supplied on this request -> nothing to prove.
        if (cloudIAM === undefined || cloudIAM === null) {
            return true;
        }

        // A blank role is a disconnect request, which is always allowed.
        if (isScraperRoleDisconnect(cloudIAM)) {
            return true;
        }

        // A settings block that names no role at all is invalid (it is not a disconnect).
        if (scraperRoleBlockNamesNoRole(cloudIAM)) {
            return false;
        }

        const { iamRoleArn, externalId } = cloudIAM;

        // 1. Prove the role can be assumed with the supplied external id.
        let credentials;
        try {
            const sts = new STSClient({ region: 'us-east-1' });
            const { Credentials } = await sts.send(
                new AssumeRoleCommand({
                    RoleArn: iamRoleArn,
                    RoleSessionName: 'meteringco-scraper-role-validation',
                    ExternalId: externalId ? externalId : undefined,
                }),
            );
            credentials = Credentials;
        } catch (e) {
            AssumableScraperRoleRule.logger.warn(
                `Scraper role ${iamRoleArn} could not be assumed with the supplied external id: ${e?.name ?? e}`,
            );
            return false;
        }

        if (!credentials) {
            return false;
        }

        // 2. Prove the returned credentials can read the instance inventory used by collection.
        try {
            await getInstanceWithFilters('us-east-1', {
                accessKeyId: credentials.AccessKeyId,
                secretAccessKey: credentials.SecretAccessKey,
                sessionToken: credentials.SessionToken,
            });
            return true;
        } catch (e) {
            AssumableScraperRoleRule.logger.warn(
                `Scraper role ${iamRoleArn} cannot read the EC2 instance inventory used for collection: ${
                    e?.message ?? e
                }`,
            );
            return false;
        }
    }

    defaultMessage(_args: ValidationArguments) {
        return (
            'cloudIAM: The provided IAM role could not be assumed with the supplied external id, ' +
            'or the returned credentials cannot read the EC2 instance inventory used for collection.'
        );
    }
}

export function AssumableScraperRole(validationOptions?: ValidationOptions) {
    return function (object: unknown, propertyName: string) {
        registerDecorator({
            name: 'AssumableScraperRole',
            target: object.constructor,
            propertyName: propertyName,
            options: validationOptions,
            validator: AssumableScraperRoleRule,
        });
    };
}
